public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Create an empty mapping from graph to graph
    IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<>(graph);

    // Iterate over the vertices and edges of the input graph
    for (V vertex : graph.getVertices()) {
        for (E edge : graph.getOutEdges(vertex)) {
            // Get the source and destination vertices of the edge
            V source = edge.getSource();
            V destination = edge.getDestination();

            // If the edge is an undirected edge
            if (edge.getIsDirected() == false) {
                // Add the edge to the mapping with the same source and destination vertices
                mapping.addEdge(source, destination, edge);
            }
            // If the edge is a directed edge
            else {
                // Add the edge to the mapping with the source vertex mapped to the destination vertex
                // and the destination vertex mapped to the source vertex
                mapping.addEdge(source, destination, edge);
                mapping.addEdge(destination, source, edge);
            }
        }
    }

    // Return the mapping
    return mapping;
}

