void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    Set<V> allVertices = new HashSet<>();
    for (V vertex : target.getVertices()) {
        allVertices.add(vertex);
    }
    // partition vertices into two sets based on their position in the graph
    Set<V> leftVertices = new HashSet<>();
    Set<V> rightVertices = new HashSet<>();
    for (V vertex : allVertices) {
        if (vertex.getPosition().x < target.getCenterX()) {
            leftVertices.add(vertex);
        } else {
            rightVertices.add(vertex);
        }
    }
    // add edges between pairs of vertices in opposite sets
    for (V vertex : leftVertices) {
        for (V otherVertex : rightVertices) {
            target.addEdge(vertex, otherVertex);
        }
    }
    // set up the result map
    for (V vertex : allVertices) {
        resultMap.put(vertex.getID(), vertex);
    }
}

