    return buffer.capacity();
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Get the encoded length of the message
    int encodedLength = schema.getEncodedLength(message);

    // Create a ByteBuf with the encoded length and write the type byte
    ByteBuf loc0 = Unpooled.buffer(encodedLength + 1);
    loc0.writeByte(schema.getTypeId());

    // Encode the message into the ByteBuf
    encode(loc0, message, schema, buffer);

    // Write the serialized message with length prefix to the OutputStream
    out.write(loc0.nioBuffer());
    return loc0.nioBuffer().remaining();
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    LinkedBuffer loc0 = buffer.novaBuffer(10);
    schema.serialize(message, buffer);
    int size = buffer.size();
    size = CodedOutputStream.computeLength(size);
    byte[] len = intToByteArr(size);
    loc0.write(len, 0, len.length);
    loc0.write(buffer.getWriterPosition(), 0, size);
    out.write(loc0.getCurrentBuffer(), 0, loc0.size);
