public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {

    // create a var to store the message length
    int messageLength = 0;

    // get the byte array representation of the message
    byte[] messageBytes = schema.toByteArray(message);
    messageLength += messageBytes.length;

    // get the linked buffer to store the message length and bytes
    int linkedBufferLength = buffer.writeInt32NoTag(messageLength);
    messageLength += linkedBufferLength;

    // write the message bytes to the output stream
    out.write(messageBytes);

    // return the size of the message
    return messageLength;
}

