}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Type[] typeArguments = targetType.getTypeParameters();
    for (int i = 0; i < typeArguments.length; i++) {
        if (typeVariable.getGenericDeclaration().equals(typeArguments[i])) {
            return (Class<?>) typeArguments[i];
        }
    }
    return Object.class;
}

Class<?>[] resolveArguments(Type genericType,Class<?> targetType){
	if (genericType instanceof ParameterizedType) {
		Type[] typeArgs = ((ParameterizedType) genericType).getActualTypeArguments();
		Class<?>[] args = new Class<?>[typeArgs.length];
		for (int i = 0; i < typeArgs.length; i++) {
			Type typeArg = typeArgs[i];
			if (typeArg instanceof TypeVariable) {
				TypeVariable<?> typeVar = (TypeVariable<?>) typeArg;
				args[i] = resolveTypeVariable(targetType, typeVar);
			} else if (typeArg instanceof WildcardType) {
				WildcardType wildcardType = (WildcardType) typeArg;
				args[i] = resolveBound(wildcardType.getUpperBounds()[0]);
			} else {
				args[i] = (Class<?>) typeArg;
			}
		}
		return args;
	}
	return null;
}

public Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
  if (!(genericType instanceof ParameterizedType)) {
    return null;
  }
  ParameterizedType parameterizedType = (ParameterizedType) genericType;
  Type[] typeArguments = parameterizedType.getActualTypeArguments();
  if (typeArguments.length == 0) {
    return null;
  }

  Map<TypeVariable<?>, Class<?>> typeVariableCache = new HashMap<>();
  for (TypeVariable<?> typeVariable : targetType.getTypeParameters()) {
    typeVariableCache.put(typeVariable, null);
  }

  Map<TypeVariable<?>, Class<?>> boundCache = new HashMap<>();
  for (int i = 0; i < typeArguments.length; i++) {
    Type typeArgument = typeArguments[i];
    if (typeArgument instanceof TypeVariable<?>) {
      TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
      boundCache.put(typeVariable, resolveBound(typeVariable));
    }
  }

  for (Map.Entry<TypeVariable<?>, Class<?>> entry : typeVariableCache.entrySet()) {
    TypeVariable<?> typeVariable = entry.getKey();
    for (int i = 0; i < boundCache.size(); i++) {
      Type typeArgument = boundCache.get(i);
      if (typeVariable.getName().equals(typeArgument.toString())) {
        entry.setValue(typeArgument);
      }
    }
  }

  Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
  for (int i = 0; i < typeArguments.length; i++) {
    resolvedArguments[i] = typeVariableCache.get(typeArguments[i]);
  }

  return resolvedArguments;
}

