static long compressTimeBucket(long timeBucket, int dayStep) {
    // Check if dayStep value is valid
    if (dayStep < 1 || dayStep > 31) {
        throw new IllegalArgumentException("Invalid day step value: " + dayStep);
    }

    // Get year, month, and day from timeBucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket / 100) % 100);
    int day = (int) (timeBucket % 100);

    // Re-format time bucket based on day step
    int reFormattedDay = day - dayStep;
    if (reFormattedDay < 1) {
        reFormattedDay += 30;
        if (month == 1) {
            month = 12;
            year--;
        } else {
            month--;
        }
    }
    return (long) (year * 10000 + month * 100 + reFormattedDay);
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
  long compressedBucket = 0;
  long lastDayOfBucket = timeBucket % 100;
  long firstDayOfBucket = (timeBucket - lastDayOfBucket) / 100;
  int modulo = lastDayOfBucket % dayStep;
  if (modulo > 0) {
    lastDayOfBucket = lastDayOfBucket - modulo;
  }
  compressedBucket = (firstDayOfBucket * 100) + lastDayOfBucket;
  return compressedBucket;
}

