        if (ch <= 0x007F) {
            numBytes++;
        } else if (ch <= 0x07FF) {
            numBytes += 2;
        } else if (ch <= 0xFFFF) {
            numBytes += 3;
        } else {
            numBytes += 4;
        }
    }
    return numBytes;
}

