public byte readByte() throws IOException {
    // Check if the buffer is empty
    if (buffer.isEmpty()) {
        // Refill the buffer
        fillBuffer();
    }
    // Check if the buffer is still empty
    if (buffer.isEmpty()) {
        // Throw an exception if there's no more data available
