    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    if (relativePathComponents.length == 0) {
        return path;
    }

    if (relativePathComponents[0].equals(".")) {
        return path;
    }

    if (relativePathComponents[0].equals("..")) {
        return path.substring(0, path.lastIndexOf("/"));
    }

    if (relativePathComponents.length == 1) {
        return path + "/" + relativePathComponents[0];
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < pathComponents.length; i++) {
        if (i < pathComponents.length - relativePathComponents.length) {
            sb.append(pathComponents[i]);
        } else {
            sb.append(relativePathComponents[i]);
        }
        sb.append("/");
    }
    return sb.toString();
}

