boolean isValidLine(String line, List<ProfileAnalyzeTimeRange> timeRanges) {
	for (ProfileAnalyzeTimeRange range : timeRanges) {
		if (line.startsWith(range.getStartTime()) && line.endsWith(range.getEndTime())) {
			return true;
		}
	}
	return false;
