public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        String[] parts = line.split("\\s+");
        if (parts.length > 0) {
            String threadId = parts[0];
            long timestamp = Long.parseLong(parts[1]);
            if (timeRanges.stream().anyMatch(timeRange -> timeRange.contains(timestamp))) {
                ThreadSnapshot snapshot = new ThreadSnapshot(threadId, timestamp);
                threadSnapshots.add(snapshot);
            }
        }
    }
    return threadSnapshots;
}

public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException(" file and timeRanges must not be null or empty");
    }

    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file));) {
        String line = null;
        while ((line = reader.readLine()) != null) {
            String[] splitLine = line.split(",");
            int threadId = Integer.parseInt(splitLine[0]);
            int methodId = Integer.parseInt(splitLine[1]);
            long time = Long.parseLong(splitLine[2]);
            ThreadSnapshot threadSnapshot = buildThreadSnapshot(threadId, methodId, time);
            threadSnapshots.add(threadSnapshot);
        }
    } catch (IOException e) {
        throw e;
    }

    return threadSnapshots;

}

private static ThreadSnapshot buildThreadSnapshot(int threadId, int methodId, long time) {
    ThreadSnapshot threadSnapshot = new ThreadSnapshot();
    threadSnapshot.setThreadId(threadId);
    threadSnapshot.setMethodId(methodId);
    threadSnapshot.setTime(time);
    return threadSnapshot;
}

public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
	List<ThreadSnapshot> snapshots = new ArrayList<>();
	String line;
	BufferedReader br = new BufferedReader(new FileReader(file));
	while ((line = br.readLine()) != null) {
		ThreadSnapshot snapshot = parseThreadSnapshotFromLine(line);
		if (snapshot != null) {
			snapshots.add(snapshot);
		}
	}
	return snapshots;
}

private static ThreadSnapshot parseThreadSnapshotFromLine(String line) {
	ThreadSnapshot snapshot = new ThreadSnapshot();
	try {
		String[] fields = line.split(" ");
		long timestamp = Long.parseLong(fields[0]);
		long tid = Long.parseLong(fields[1]);
		snapshot.timestamp = timestamp;
		snapshot.tid = tid;

		for (int i = 2; i < fields.length; i++) {
			if (fields[i].equals("splitting")) {
				snapshot.isSplitting = true;
			} else if (fields[i].equals("pairing")) {
				snapshot.isPairing = true;
			} else if (fields[i].startsWith("snap")) {
				snapshot.snap = Integer.parseInt(fields[i].substring(4));
			}
		}

		return snapshot;
	} catch (Exception e) {
		return null;
	}
}
